std::vector<int> buildFromPush(int n) {
    int* data = nullptr;
    int size = 0;
    int capacity = 0;
    for (int i = 0; i < n; ++i) {
        if (size == capacity) {
            int newCap = (capacity == 0) ? 1 : capacity * 2;
            int* newData = new int[newCap];
            for (int j = 0; j < size; ++j) {
                newData[j] = data[j];
            }
            delete[] data;
            data = newData;
            capacity = newCap;
        }
        data[size++] = i;
    }
    std::vector<int> result(data, data + size);
    delete[] data;
    return result;
}

