long long countGrowthCopies(int n) {
    long long copies = 0;
    int capacity = 0;
    for (int i = 0; i < n; ++i) {
        if (i == capacity) {
            copies += capacity;
            capacity = (capacity == 0) ? 1 : capacity * 2;
        }
    }
    return copies;
}

