#include <bits/stdc++.h>
using namespace std;

long long sumAll(const vector<int>& v) {      // O(n): one pass
    long long total = 0;
    for (int x : v) total += x;               // n operations
    return total;
}

long long countPairs(const vector<int>& v) {  // O(n^2): nested passes
    long long cnt = 0;
    for (size_t i = 0; i < v.size(); ++i)
        for (size_t j = i + 1; j < v.size(); ++j)
            if (v[i] < v[j]) ++cnt;           // n*(n-1)/2 operations
    return cnt;
}

int main() {
    vector<int> v = {3, 1, 4, 1, 5};
    cout << sumAll(v) << " " << countPairs(v) << "\n";
    return 0;
}

