#include <bits/stdc++.h>
using namespace std;

vector<int> selectionSort(vector<int> arr) {
    int n = (int)arr.size();
    for (int i = 0; i < n - 1; ++i) {
        int minIdx = i;                    // smallest in arr[i..n-1] so far
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[minIdx]) minIdx = j;
        }
        if (minIdx != i) swap(arr[i], arr[minIdx]);  // place it in position
    }
    return arr;
}

int main() {
    vector<int> v = {4, 2, 5, 1, 3};
    vector<int> s = selectionSort(v);
    for (int x : s) cout << x << " ";      // 1 2 3 4 5
    cout << "\n";
    return 0;
}

