#include <bits/stdc++.h>
using namespace std;

void mergeTwoHalves(vector<int>& arr, int left, int mid, int right) {
    vector<int> L(arr.begin() + left, arr.begin() + mid + 1); // copy left half
    vector<int> R(arr.begin() + mid + 1, arr.begin() + right + 1); // right half
    int i = 0, j = 0, k = left;
    while (i < (int)L.size() && j < (int)R.size()) {
        if (L[i] <= R[j]) arr[k++] = L[i++];   // '<=' keeps stability
        else              arr[k++] = R[j++];
    }
    while (i < (int)L.size()) arr[k++] = L[i++];  // leftovers
    while (j < (int)R.size()) arr[k++] = R[j++];
}

void sortRange(vector<int>& arr, int left, int right) {
    if (left >= right) return;                 // 0 or 1 elements: done
    int mid = left + (right - left) / 2;
    sortRange(arr, left, mid);                 // sort left half
    sortRange(arr, mid + 1, right);            // sort right half
    mergeTwoHalves(arr, left, mid, right);     // merge the sorted halves
}

vector<int> mergeSort(vector<int> arr) {
    sortRange(arr, 0, (int)arr.size() - 1);
    return arr;
}

int main() {
    vector<int> v = {38, 27, 43, 3, 9, 82, 10};
    for (int x : mergeSort(v)) cout << x << " ";   // 3 9 10 27 38 43 82
    cout << "\n";
    return 0;
}

